/** 경도 → viewBox x */
export const mapX = (lon: number) => ((lon + 180) / 360) * MAP_W;
/** 위도 → viewBox y */
export const mapY = (lat: number) => ((MAP_LAT_TOP - lat) / MAP_LAT_SPAN) * MAP_H;

